  'dashboard.tour.welcome.title': 'KŌMA Studio 대시보드에 오신 것을 환영합니다',
  'dashboard.tour.welcome.body':
    '이 투어에서는 앱의 주요 흐름을 안내합니다: 페이지 정리, 모드 선택, AIO 파이프라인 설정, 결과 내보내기까지 각 기능의 위치를 추측할 필요 없이 진행할 수 있습니다.',
