  'dashboard.tour.sidebar.body':
    '여기서 플랜과 월간 사용량을 추적하고, 활성 이미지를 선택하고, 페이지 순서를 변경하고, 항목을 제거하며, 처리 전에 배치를 정리할 수 있습니다.',
  'dashboard.tour.upload.title': '초기 파일 입력',
  'dashboard.tour.upload.body':
    '드롭존은 개별 이미지와 전체 패키지를 모두 허용합니다. 챕터, 원본 또는 에셋을 드래그하여 대시보드의 나머지 부분에 공급하는 시작점입니다.',
  'dashboard.tour.modes.title': '메인 대시보드 탐색',
  'dashboard.tour.modes.body':
    '정리를 사용하여 배치를 준비하고 AIO로 전체 파이프라인을 실행하세요. 다른 상단 도구 모음 그룹은 작업 공간을 벗어나지 않고 전문 모드를 엽니다.',
  'dashboard.tour.production.title': '프로덕션: 전문 도구',
  'dashboard.tour.production.body':
    '클리너, 타이프세터, 번역기, 원본, QC는 수동 및 고급 워크플로를 다룹니다. 이 그룹을 특정 챕터 단계에서 작업하기 위한 전문 모드로 생각하세요.',
  'dashboard.tour.utils.title': '유틸리티 및 지원',
  'dashboard.tour.utils.body':
    '이어 붙이기, 분할, 워터마크, 향상은 빠른 준비 및 내보내기 작업을 처리합니다. 가이드와 리소스가 참고를 위한 지원 영역을 완성합니다.',
  'dashboard.tour.submode.title': '자동 AIO vs. 수동',
  'dashboard.tour.submode.body':
    '자동은 배치에서 전체 파이프라인을 실행합니다. 수동은 이미지별로 각 단계를 잠금 해제하여 세밀한 검토, 되감기/앞으로 및 제어된 시각적 편집을 제공합니다.',
  'dashboard.tour.pipeline.title': 'AIO 파이프라인',
  'dashboard.tour.pipeline.body':
    '이 카드는 감지 > OCR > 번역 > 분할 > 클린 > 렌더 시퀀스를 제어합니다. 단계를 활성화하거나 비활성화할 수 있으며, 수동 모드에서는 현재 단계만 실행할 수 있습니다.',
  'dashboard.tour.stageConfig.title': '단계 설정',
  'dashboard.tour.stageConfig.body':
    '여기서 언어, AIO 프리셋, 로컬/클라우드 카탈로그 및 단계별 모델 선택을 찾을 수 있습니다. 비용, 품질, 속도를 조정하기 위한 의사결정 센터입니다.',
  'dashboard.tour.stage.withImagesTitle': '작업 공간 및 시각적 미리보기',
  'dashboard.tour.stage.withImagesBody':
    '이미지가 있으면 이 스테이지가 메인 미리보기가 됩니다: 페이지를 탐색하고, 단계별 결과를 확인하고, 활성 이미지에서 직접 작업합니다.',
  'dashboard.tour.stage.emptyTitle': '대시보드 중앙 스테이지',
  'dashboard.tour.stage.emptyBody':
    '이미지가 없으면 스테이지에 간단한 빈 상태가 표시됩니다. 업로드 후 모드별 미리보기, 오버레이, 영역 및 결과가 표시됩니다.',
  'dashboard.tour.manualDock.title': '인터랙티브 미리보기 및 수동 독',
  'dashboard.tour.manualDock.body':
    '수동 AIO에서 활성 이미지가 있으면 플로팅 독이 영역 선택, 브러시, 지우개, 지팡이, 힐링 및 컨텍스트 조정을 미리보기에서 벗어나지 않고 잠금 해제합니다.',
  'dashboard.tour.download.title': '내보내기 및 다운로드',
